% ----------------------------------------------------------------------
%   Spherical Linear Intepolation (slerp) and 
%   Screw Linear Interpolation (sclerp)
%    20210108  y.yoshimura
%    Inputs:
%   Outputs:
%   related function files:
%   note:
%   cf:
%   revisions;
%   
%   (c) 2021 yasuhiro yoshimura
%----------------------------------------------------------------------

clc
clear
close all

%[text] ## load object
sat = readSC('oneWeb.obj'); %[output:176ffd26]

showSC(sat) %[output:4d48d46e]

%[text] ## quaternions to be interpolated
q1 = [0 0 0 1];
q1 = rand(1,4);
q1 = q1 ./ norm(q1);

q2 = rand(1,4);
q2 = q2 ./ norm(q2);

%[text] ## slerp
dt = 0.01;
t = 0:dt:1;

% interpolated quaternion, q1 → q2
qt = slerp(t, 4, q1, q2);

tiledlayout(4,1); %[output:4d48d46e] %[output:3d4f223c]
nexttile %[output:3d4f223c]
plot(t(1), q1(1), 'o'); %[output:3d4f223c]
hold on %[output:3d4f223c]
plot(t, qt(:,1)); %[output:3d4f223c]
plot(t(end), q2(1), 'o'); %[output:3d4f223c]
nexttile %[output:3d4f223c]
plot(t(1), q1(2), 'o'); %[output:3d4f223c]
hold on %[output:3d4f223c]
plot(t, qt(:,2)); %[output:3d4f223c]
plot(t(end), q2(2), 'o'); %[output:3d4f223c]
nexttile %[output:3d4f223c]
plot(t(1), q1(3), 'o'); %[output:3d4f223c]
hold on %[output:3d4f223c]
plot(t, qt(:,3)); %[output:3d4f223c]
plot(t(end), q2(3), 'o'); %[output:3d4f223c]
nexttile %[output:3d4f223c]
plot(t(1), q1(4), 'o'); %[output:3d4f223c]
hold on %[output:3d4f223c]
plot(t, qt(:,4)); %[output:3d4f223c]
plot(t(end), q2(4), 'o'); %[output:3d4f223c]

%[text] ## sclerp
rI1 = [0 0.1 0.3]; % translation
dq1r = rand(1,4); % real part
dq1r = dq1r ./ norm(dq1r);
dq1r = [0 0 0 1];

dq1d = 0.5 .* qMult(4, 1, dq1r, [rI1 0]); % dual part
dq1 = [dq1r, dq1d];

rI2 = [0 0 1]; % translation
dq2r = rand(1,4); % real part
dq2r = dq2r ./ norm(dq2r);

dq2d = 0.5 .* qMult(4, 1, dq2r, [rI2 0]);
dq2 = [dq2r, dq2d];

% interpolated dual quaternion, dq1 → dq2
dqt = sclerp(t, 4, dq1, dq2);

[rI, q] = dq2pos(1, 4, dqt);


figure %[output:14aacf1c]
plot3(rI(:,1), rI(:,2), rI(:,3)) %[output:14aacf1c]
axis equal %[output:14aacf1c]

%[text] ## show DQ figs
figure % real part %[output:8de86020]
tiledlayout(4,1); %[output:8de86020]
nexttile %[output:8de86020]
plot(t(1), dq1(1), 'o'); %[output:8de86020]
hold on %[output:8de86020]
plot(t, dqt(:,1)); %[output:8de86020]
plot(t(end), dq2(1), 'o'); %[output:8de86020]
nexttile %[output:8de86020]
plot(t(1), dq1(2), 'o'); %[output:8de86020]
hold on %[output:8de86020]
plot(t, dqt(:,2)); %[output:8de86020]
plot(t(end), dq2(2), 'o'); %[output:8de86020]
nexttile %[output:8de86020]
plot(t(1), dq1(3), 'o'); %[output:8de86020]
hold on %[output:8de86020]
plot(t, dqt(:,3)); %[output:8de86020]
plot(t(end), dq2(3), 'o'); %[output:8de86020]
nexttile %[output:8de86020]
plot(t(1), dq1(4), 'o'); %[output:8de86020]
hold on %[output:8de86020]
plot(t, dqt(:,4)); %[output:8de86020]
plot(t(end), dq2(4), 'o'); %[output:8de86020]

figure % dual part %[output:16ceb557]
tiledlayout(4,1); %[output:16ceb557]
nexttile %[output:16ceb557]
plot(t(1), dq1(5), 'o'); %[output:16ceb557]
hold on %[output:16ceb557]
plot(t, dqt(:,5)); %[output:16ceb557]
plot(t(end), dq2(5), 'o'); %[output:16ceb557]
nexttile %[output:16ceb557]
plot(t(1), dq1(6), 'o'); %[output:16ceb557]
hold on %[output:16ceb557]
plot(t, dqt(:,6)); %[output:16ceb557]
plot(t(end), dq2(6), 'o'); %[output:16ceb557]
nexttile %[output:16ceb557]
plot(t(1), dq1(7), 'o'); %[output:16ceb557]
hold on %[output:16ceb557]
plot(t, dqt(:,7)); %[output:16ceb557]
plot(t(end), dq2(7), 'o'); %[output:16ceb557]
nexttile %[output:16ceb557]
plot(t(1), dq1(8), 'o'); %[output:16ceb557]
hold on %[output:16ceb557]
plot(t, dqt(:,8)); %[output:16ceb557]
plot(t(end), dq2(8), 'o'); %[output:16ceb557]

